# Find connected components
def find_clusters(grid):
    height, width = len(grid), len(grid[0])
    visited = [[False]*width for _ in range(height)]
    clusters = []

    for r in range(height):
        for c in range(width):
            if grid[r][c] != 0 and not visited[r][c]:
                cluster = {}
                queue = deque([(r, c, grid[r][c])])
                visited[r][c] = True
                while queue:
                    cr, cc, color = queue.popleft()
                    if color not in cluster:
                        cluster[color] = []
                    cluster[color].append((cr, cc))

                    for dr, dc in [(0,1), (0,-1), (1,0), (-1,0)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < height and 0 <= nc < width and grid[nr][nc] == color and not visited[nr][nc]:
                            visited[nr][nc] = True
                            queue.append((nr, nc, color))
                clusters.append(cluster)
    return clusters

clusters = find_clusters(test_input)
print(f"\nFound {len(clusters)} connected clusters (clusters of different colors):")
for i, clus in enumerate(clusters):
    for color, positions in sorted(clus.items()):
        print(f"  Cluster {i}: Color {color} at {positions} (count: {len(positions)})")

